'use strict';

const util = require('util');
const stringifySafe = require('json-stringify-safe');

module.exports = data => {
    let result = util.format('%j', data);

    // Рассчитываем, что циклические ссылки – не очень частый кейс в логах
    if (result === '[Circular]') {
        result = stringifySafe(data);
    }

    return result;
};
